// LLC order pricing: ONE source of truth for the cart on /llc-formation/ and for the
// Stripe checkout function (functions/api/llc-checkout.js imports this same file).
// Prices come from the pricing object generated by tools/build_llc.py (never typed here).

export function selectionFromForm(f) {
  // f: plain object of form fields (strings / "yes")
  return {
    package: f.package || "",
    state: String(f.state || "").toUpperCase(),
    bk: { on: f.monthly_bookkeeping === "yes", accounts: f.bk_accounts || "", volume: f.bk_volume || "" },
    f1099: { on: f.addon_1099 === "yes", forms: f.f1099_forms || "" },
    salestax: f.addon_salestax === "yes",
    scorp: f.addon_scorp === "yes",
    quarterly: f.addon_quarterly === "yes",
  };
}

export function computeOrder(P, sel) {
  const pkg = P.packages[sel.package];
  const st = P.states[sel.state];
  const A = P.addons;
  const today = [], recurring = [], included = [], notes = [];
  const money = (n) => Math.round(n * 100);
  if (pkg) today.push({ key: "pkg", name: `${pkg.name} (MFA LLC formation package)`, amount: money(pkg.price) });
  if (st) {
    if (st.fee != null) today.push({ key: "fee", name: `${st.name} state filing fee (paid to the state at cost)`, amount: money(st.fee) });
    else notes.push(`${st.name}'s filing fee isn't included today: we confirm it before filing and charge it at cost.`);
    if (st.extra) today.push({ key: "extra", name: `${st.name} fees also due at formation (paid to the state at cost)`, amount: money(st.extra) });
    if (st.pub_fee) today.push({ key: "pub", name: `${st.name} Certificate of Publication fee (paid to the state at cost)`, amount: money(st.pub_fee) });
    if (st.pub) notes.push(`${st.name} requires newspaper publication; newspaper costs are billed at cost when the county sets them.`);
  }
  const inc = (k) => (A[k].included_in || []).includes(sel.package);
  for (const k of ["salestax", "scorp"]) {
    if (inc(k)) included.push({ key: k, name: A[k].name });
    else if (sel[k]) today.push({ key: k, name: A[k].name, amount: money(A[k].price) });
  }
  if (sel.f1099 && sel.f1099.on) {
    const n = Math.max(1, Math.min(250, parseInt(sel.f1099.forms, 10) || 1));
    today.push({ key: "f1099", name: `${A.f1099.name} (${n} form${n > 1 ? "s" : ""}, $${A.f1099.per} each, $${A.f1099.min} minimum)`, amount: money(Math.max(A.f1099.min, A.f1099.per * n)) });
  }
  if (sel.quarterly) {
    today.push({ key: "quarterly", name: `${A.quarterly.name} (next ${A.quarterly.quarters} quarters at $${A.quarterly.per_quarter} each)`, amount: money(A.quarterly.per_quarter * A.quarterly.quarters) });
  }
  let bk = null;
  if (sel.bk && sel.bk.on) {
    const acc = sel.bk.accounts, vol = sel.bk.volume;
    const tier = A.bk.tiers.find((t) => String(t.id) === String(vol));
    const nAcc = parseInt(acc, 10);
    if (!acc || !vol) bk = { incomplete: true };
    else if (!tier || !(nAcc >= 1 && nAcc <= A.bk.max_accounts)) bk = { quote: true };
    else {
      const price = A.bk.base + Math.max(0, nAcc - A.bk.incl_accounts) * A.bk.per_account + tier.add;
      bk = { price };
      recurring.push({ key: "bk", name: `Monthly bookkeeping (${nAcc} account${nAcc > 1 ? "s" : ""}, ${tier.label})`, amount: money(price), interval: "month", trial_days: A.bk.trial_days });
    }
    if (bk.quote) notes.push(`Monthly bookkeeping for more than ${A.bk.max_accounts} accounts or over ${A.bk.tiers[A.bk.tiers.length - 1].max} transactions a month is quoted after a short review; nothing is charged for it today.`);
  }
  const total = today.reduce((a, l) => a + l.amount, 0);
  return { ok: !!pkg && !!st, pkg, st, today, recurring, included, notes, bk, total };
}
